inline const char* tr(const char* s) { for(const auto& e:entries) if(!strcmp(e.source,s)) return BRUXOS_LANGUAGE==2?e.zh:BRUXOS_LANGUAGE==1?e.en:e.pt; return s; }
inline const char* options(const char* s) { static std::mutex mutex; std::lock_guard<std::mutex> guard(mutex); static std::map<std::string,std::string> cache; auto found=cache.find(s); if(found!=cache.end())return found->second.c_str(); std::string source=s,result; size_t start=0; for(;;){auto end=source.find('|',start); if(start)result+='|';result+=tr(source.substr(start,end-start).c_str());if(end==std::string::npos)break;start=end+1;}return cache.emplace(source,result).first->second.c_str(); }
inline const char* paramName(const char* s) { static std::mutex mutex; std::lock_guard<std::mutex> guard(mutex); static std::map<std::string,std::string> cache; auto found=cache.find(s);if(found!=cache.end())return found->second.c_str();std::string value=tr(s);if(value.size()>31){size_t end=31;while(end&&((unsigned char)value[end]&0xc0)==0x80)--end;value.resize(end);}return cache.emplace(s,value).first->second.c_str(); }
